begin;
create function pg_temp.check_routing(ok boolean, message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Routing: %',message; end if; end$$;
insert into auth.users(id,email) values ('91000000-0000-0000-0000-000000000281','routing-admin@example.test'),('91000000-0000-0000-0000-000000000282','routing-employee@example.test');
insert into public.organizations(id,name,slug) values ('91000000-0000-0000-0000-000000000283','Routing regression','routing-regression'),('91000000-0000-0000-0000-000000000284','Other routing regression','other-routing-regression');
insert into public.organization_memberships(organization_id,user_id,role) values ('91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','administrator'),('91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000282','end_user');
insert into public.teams(id,organization_id,name) values ('91000000-0000-0000-0000-000000000285','91000000-0000-0000-0000-000000000283','Default support'),('91000000-0000-0000-0000-000000000286','91000000-0000-0000-0000-000000000283','Override support'),('91000000-0000-0000-0000-000000000287','91000000-0000-0000-0000-000000000284','Foreign support');
insert into public.ticket_categories(id,organization_id,name,default_team_id) values ('91000000-0000-0000-0000-000000000288','91000000-0000-0000-0000-000000000283','Routing category','91000000-0000-0000-0000-000000000285');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub','91000000-0000-0000-0000-000000000281','aal','aal1')::text,true);
do $$begin
 begin update public.ticket_categories set default_team_id='91000000-0000-0000-0000-000000000287' where id='91000000-0000-0000-0000-000000000288'; raise exception 'Cross-tenant routing allowed'; exception when foreign_key_violation then null; end;
end$$;
insert into public.tickets(id,organization_id,requester_id,title,description,category_id) values ('91000000-0000-0000-0000-000000000289','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','Automatic request','Details','91000000-0000-0000-0000-000000000288');
select pg_temp.check_routing((select team_id='91000000-0000-0000-0000-000000000285' and routing_mode='automatic' from public.tickets where id='91000000-0000-0000-0000-000000000289'),'automatic assignment');
select pg_temp.check_routing((select count(*)=1 from public.ticket_activity where ticket_id='91000000-0000-0000-0000-000000000289' and action='automatically_routed' and details->>'team_name'='Default support'),'routing history snapshot');
insert into public.tickets(id,organization_id,requester_id,title,description,category_id,team_id) values ('91000000-0000-0000-0000-000000000290','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','Manual request','Details','91000000-0000-0000-0000-000000000288','91000000-0000-0000-0000-000000000286');
select pg_temp.check_routing((select team_id='91000000-0000-0000-0000-000000000286' and routing_mode='manual' from public.tickets where id='91000000-0000-0000-0000-000000000290'),'explicit team wins');
insert into public.tickets(id,organization_id,requester_id,title,description,category_id,routing_mode) values ('91000000-0000-0000-0000-000000000291','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','Unassigned request','Details','91000000-0000-0000-0000-000000000288','manual');
select pg_temp.check_routing((select team_id is null from public.tickets where id='91000000-0000-0000-0000-000000000291'),'explicit unassigned wins');
insert into public.tickets(id,organization_id,requester_id,title,description) values ('91000000-0000-0000-0000-000000000292','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','Unmatched request','Details');
select pg_temp.check_routing((select team_id is null from public.tickets where id='91000000-0000-0000-0000-000000000292'),'no match stays unassigned');
insert into public.assets(id,organization_id,tag,name,kind,status,assigned_user_id) values ('91000000-0000-0000-0000-000000000293','91000000-0000-0000-0000-000000000283','ROUTING-TEST','Routing laptop','computer','in_use','91000000-0000-0000-0000-000000000282');
select set_config('request.jwt.claims',json_build_object('sub','91000000-0000-0000-0000-000000000282','aal','aal1')::text,true);
with changed as (update public.ticket_categories set default_team_id='91000000-0000-0000-0000-000000000286' where id='91000000-0000-0000-0000-000000000288' returning id) select pg_temp.check_routing((select count(*)=0 from changed),'employee cannot change routing policy');
insert into public.tickets(id,organization_id,requester_id,title,description,category_id,routing_mode,team_id) values ('91000000-0000-0000-0000-000000000294','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000282','Employee request','Details','91000000-0000-0000-0000-000000000288','manual','91000000-0000-0000-0000-000000000286');
select pg_temp.check_routing((select team_id='91000000-0000-0000-0000-000000000285' from public.tickets where id='91000000-0000-0000-0000-000000000294'),'employee cannot forge override');
select public.create_equipment_ticket('91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000293','Equipment request','Details','91000000-0000-0000-0000-000000000288');
-- Asset associations are staff-only; verify the result as the administrator.
select set_config('request.jwt.claims','{"sub":"91000000-0000-0000-0000-000000000281","aal":"aal1"}',true);
select pg_temp.check_routing((select count(*)=1 from public.tickets t join public.ticket_assets a on a.ticket_id=t.id and a.organization_id=t.organization_id where a.asset_id='91000000-0000-0000-0000-000000000293' and t.team_id='91000000-0000-0000-0000-000000000285'),'equipment routed atomically');
select set_config('request.jwt.claims',json_build_object('sub','91000000-0000-0000-0000-000000000281','aal','aal1')::text,true);
update public.teams set is_active=false where id='91000000-0000-0000-0000-000000000285';
insert into public.tickets(id,organization_id,requester_id,title,description,category_id) values ('91000000-0000-0000-0000-000000000295','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','Inactive team request','Details','91000000-0000-0000-0000-000000000288');
select pg_temp.check_routing((select team_id is null from public.tickets where id='91000000-0000-0000-0000-000000000295'),'inactive teams skipped');
update public.ticket_categories set default_team_id='91000000-0000-0000-0000-000000000286' where id='91000000-0000-0000-0000-000000000288';
select pg_temp.check_routing((select team_id='91000000-0000-0000-0000-000000000285' from public.tickets where id='91000000-0000-0000-0000-000000000289'),'policy edits preserve existing tickets');
update public.ticket_categories set is_active=false where id='91000000-0000-0000-0000-000000000288';
insert into public.tickets(id,organization_id,requester_id,title,description,category_id) values ('91000000-0000-0000-0000-000000000296','91000000-0000-0000-0000-000000000283','91000000-0000-0000-0000-000000000281','Inactive category request','Details','91000000-0000-0000-0000-000000000288');
select pg_temp.check_routing((select team_id is null from public.tickets where id='91000000-0000-0000-0000-000000000296'),'inactive categories skipped');
select 'Routing regression passed; all fixtures rolled back' as result;
rollback;
